            with open(os.path.join(t, "DESIGN.md"), encoding="utf-8") as f:
                text = f.read()
            for title in ("Overview", "Colors", "Typography", "Layout", "Shapes", "Motion", "Accessibility"):
                sec = text.split(f"\n## {title}\n", 1)[1].split("\n## ", 1)[0]
