    def test_unusable_values_are_not_mapped_and_multi_value_override(self):
        data = {"version": 1, "themes": [], "standards": [
            {"id": "STD-t-01", "theme": "t", "title": "Two values", "rule": "Enter and exit curves are fixed.", "strength": "must",
             "engine": [{"path": "motion.easing.enter", "value": [0, 0, 0.2, 1]}, {"path": "motion.easing.exit", "value": [0.4, 0, 1, 1]}],
             "since": 1, "changed": 1},
            {"id": "STD-t-02", "theme": "t", "title": "Faint text", "rule": "Body text is light gray.", "strength": "must",
             "engine": {"path": "color.text.primary", "value": "#dddddd"}, "since": 1, "changed": 1},
            {"id": "STD-t-03", "theme": "t", "title": "Bad parameter", "rule": "Containers use an alias.", "strength": "must",
             "engine": {"path": "radius.container", "value": "{radius.8}"}, "since": 1, "changed": 1},
            {"id": "STD-t-04", "theme": "t", "title": "Wrong type", "rule": "Exit is a duration.", "strength": "must",
             "engine": {"path": "motion.easing.linear", "value": [0, 0, 1, 1], "type": "duration"}, "since": 1, "changed": 1}]}
        with tempfile.TemporaryDirectory() as t, house_standards(write_std(t, "std.json", data)):
            d = os.path.join(t, "opendesigner")
            quiet(e.cmd_init, d, name="Floors")
            state = e.read_json(os.path.join(d, "state.json"))
            self.assertEqual(state["overrides"], {"motion.easing.enter": [0, 0, 0.2, 1], "motion.easing.exit": [0.4, 0, 1, 1]})
            self.assertEqual(state["standards"]["applied"], ["STD-t-01", "STD-t-02", "STD-t-03", "STD-t-04"])
            quiet(e.cmd_build, d)
            self.assertEqual(e.validate_dir(d).count("error"), 0)                 # accessibility floors outrank a standard
            un = {u["id"]: u["reason"] for u in e.std_unmapped(e.merge_defaults(state), e.load_standards())}
            self.assertEqual(sorted(un), ["STD-t-02", "STD-t-03", "STD-t-04"])
            self.assertIn("would break a check the engine enforces", un["STD-t-02"])
            self.assertIn("needs 4.5:1", un["STD-t-02"])
            self.assertIn("radius.container takes a corner radius in whole px", un["STD-t-03"])  # names what it takes
            self.assertIn("cubicBezier token, but the standard gives a duration", un["STD-t-04"])
            with self.assertRaises(SystemExit) as cm:
                quiet(e.cmd_standard, d, "override", sid="STD-t-01", why="ours", value=[0, 0, 1, 1])
            self.assertIn("sets 2 values", str(cm.exception))
            quiet(e.cmd_standard, d, "override", sid="STD-t-01", why="our motion guide")
            locks = e.read_json(os.path.join(d, "state.json"))["locks"]
            self.assertFalse([x for x in locks if x.startswith("overrides.motion.easing")])

    def test_project_standard_wins_over_house_standard(self):
        with tempfile.TemporaryDirectory() as t:
            v1, v2 = write_std(t, "v1.json", STD_V1), write_std(t, "v2.json", std_v2())
            d = os.path.join(t, "opendesigner")
            with house_standards(v1):
                quiet(e.cmd_init, d, name="Brand wins")
                out = io.StringIO()
                with contextlib.redirect_stdout(out):
                    e.cmd_standard(d, "add", rule="Exits ease in, per our brand guide.", why="brand guide", source="https://example.com/g",
                                   path="motion.easing.exit", value=[0.5, 0, 1, 1])
                self.assertIn("wins over house standard STD-easing-duration-01", out.getvalue())
                quiet(e.cmd_generate, d)
                self.assertFalse([i for i in e.validate_dir(d).items if i["category"] == "standards"])   # no drift reported
                with self.assertRaises(SystemExit) as cm:
                    quiet(e.cmd_set, d, "motion.easing.exit", [0, 0, 1, 1], "try")
