                self.assertEqual(state["standards"]["records"]["STD-easing-duration-01"]["kept"], {"overrides.motion.easing.exit": "PRJ-01"})
                quiet(e.cmd_build, d)
                with open(os.path.join(t, "DESIGN.md"), encoding="utf-8") as f:
                    self.assertIn("Your project standard PRJ-01 wins here.", f.read())

